WITH base AS (SELECT *, INITCAP(TRIM(page)) AS page_title, INITCAP(TRIM(page)) AS page_title_2 FROM web_events WHERE event_time >= TIMESTAMP '2023-09-19 00:00:00' AND session_id IN (3, 26, 29, 40)), flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM base), sessions_web_events AS (SELECT id, session_id, event_time, page_title, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT session_id, ROUND(AVG(island_id), 2) AS avg_island_id, COUNT(*) AS row_count, ROUND(AVG(island_id), 2) AS avg_island_id_2, GROUPING_ID() AS gid FROM sessions_web_events GROUP BY ROLLUP (session_id) ORDER BY avg_island_id DESC NULLS FIRST
